<?php
declare(strict_types=1);
require dirname(__DIR__) . '/vendor/autoload.php';
use SimpleStore\Accounting\{TaxEvidenceRepository,TaxMoney,OrderFundsRepository,TaxRegisterRepository,InvoiceCorrectionRepository,EvidenceBookRepository};
use SimpleStore\Database\{ConnectionFactory,SchemaUpdater};
$db = ConnectionFactory::create(['host'=>'127.0.0.1','user'=>'root','password'=>(string)getenv('MYSQL_TEST_PASSWORD'),'database'=>'simple_store','port'=>3306]);
(new SchemaUpdater($db,dirname(__DIR__).'/database/schema.sql'))->apply();
$assert = static function (bool $ok,string $message):void { if (!$ok) throw new RuntimeException($message); };
$reject = static function (callable $fn) use ($assert):void { try {$fn();} catch (InvalidArgumentException) {return;} $assert(false,'Invalid or duplicate write accepted.'); };
$tax = new TaxEvidenceRepository($db); $funds = new OrderFundsRepository($db); $register = new TaxRegisterRepository($db); $corrections = new InvoiceCorrectionRepository($db);
$year=2096; $date='2096-06-01'; $suffix=bin2hex(random_bytes(4));
$items = [['name'=>'Boty','product_key'=>str_repeat('b',32),'quantity'=>1,'unit_price_czk'=>1800,'sale_mode'=>'assisted','supplier_price_czk'=>1678,'assistance_fee_czk'=>122,
    'seller'=>['name'=>'Dodavatel','ico'=>'12345678','address'=>'Praha 1','email'=>'seller@example.test','terms_url'=>'https://example.test/terms']]];
$db->insert('shop_orders',['order_number'=>'EVID-'.$suffix,'status'=>'new','customer_email'=>'evidence@example.test','subtotal_czk'=>1800,'shipping_czk'=>0,'total_czk'=>1800,'items_json'=>json_encode($items,JSON_THROW_ON_ERROR),'shipping_json'=>'{}','payment_method'=>'bank_transfer','payment_status'=>'pending','created_at'=>$date.' 10:00:00']);
$id=(int)$db->insertId();
$base=['entry_date'=>$date,'account'=>'bank','own_czk'=>'122','principal_czk'=>'1678','movement'=>'receipt','reference'=>'BANK-'.$suffix,'request_key'=>bin2hex(random_bytes(16))];
$before=$tax->summary($year);
$funds->record($id,$base); // actual receipts are permitted before order status reconciliation
$assert($funds->totals($id)['held']==='1678.00','Entrusted funds not split.');
$assert($tax->summary($year)['income']-$before['income']===122,'Principal counted as taxable revenue.');
$reject(fn()=>$funds->record($id,$base));
$assert(count($funds->entries($id))===2,'Retry duplicated receipt rows.');
$funds->record($id,array_replace($base,['movement'=>'supplier_payment','own_czk'=>'0','principal_czk'=>'1678','request_key'=>bin2hex(random_bytes(16)),'entry_date'=>'2096-06-02']));
$assert($funds->totals($id)['held']==='0.00' && $tax->summary($year)['expenses']===$before['expenses'],'Supplier purchase became deductible.');
$book=(new EvidenceBookRepository($db))->page($year,0,'EVID-'.$suffix)['items'];
$assert(count($book)===1 && $book[0]['receipt_amount_czk']===1800 && $book[0]['receipt_date']===$date && $book[0]['activity_date']==='2096-06-02','Supplier payment replaced the customer receipt.');
$funds->record($id,array_replace($base,['movement'=>'supplier_return','own_czk'=>'0','principal_czk'=>'1678','request_key'=>bin2hex(random_bytes(16))]));
$funds->record($id,array_replace($base,['movement'=>'refund','own_czk'=>'12,25','principal_czk'=>'100,10','request_key'=>bin2hex(random_bytes(16))]));
$assert($funds->totals($id)['held']==='1577.90','Partial principal return not reconciled exactly.');
$assert(abs($tax->summary($year)['income']-$before['income']-109.75)<0.0001,'Own refund did not reduce revenue by cents.');
$assert($tax->orderReceipt($id)['amount_czk']=='1800.00','Supplier return inflated customer receipt.');
$funds->record($id,array_replace($base,['movement'=>'receipt','own_czk'=>'0,25','principal_czk'=>'0,10','request_key'=>bin2hex(random_bytes(16))]));
$assert($tax->orderReceipt($id)['amount_czk']=='1800.35','Partial receipt cents lost.');
$pendingKey=bin2hex(random_bytes(16));
$reject(fn()=>$funds->record($id,array_replace($base,['request_key'=>$pendingKey,'account'=>'invalid'])));
$assert((int)$db->queryFirstField('SELECT COUNT(*) FROM shop_tax_write_requests WHERE request_key=%s',$pendingKey)===0,'Failed write consumed replay token.');
$expenses=$tax->summary($year)['expenses'];
$funds->transfer(['entry_date'=>$date,'amount_czk'=>'98,35','from_account'=>'clearing','to_account'=>'bank','reference'=>'TRANSFER-'.$suffix,'request_key'=>bin2hex(random_bytes(16))]);
$assert($tax->summary($year)['expenses']===$expenses,'Own transfer affected deductible expenses.');
$transfer=$tax->entriesPage($year,0,50,['q'=>'TRANSFER-'.$suffix])['items'];
$assert(count($transfer)===2 && $transfer[0]['amount_czk']===$transfer[1]['amount_czk'],'Transfer did not create balanced pair.');
$entry=$funds->entries($id)[0];
$tax->amendEntry((int)$entry['id'],['version'=>$entry['version'],'amount_czk'=>'122,15','description'=>'=formula'],1,'Oprava podle výpisu');
$reject(fn()=>$tax->amendEntry((int)$entry['id'],['version'=>$entry['version'],'amount_czk'=>'999'],1,'Zastaralá oprava zápisu'));
$reject(fn()=>$tax->voidEntry((int)$entry['id'],1,'Zastaralé vyřazení zápisu',(int)$entry['version']));
$csv=fopen('php://temp','w+b');$tax->writeLedgerCsv($csv,$year,['order_id'=>(string)$id,'tax_kind'=>'taxable']);rewind($csv);$export=stream_get_contents($csv);fclose($csv);
$assert(str_contains($export,"'=formula") && str_contains($export,'122.15') && !str_contains($export,'1678.00'),'Filtered export lost decimals, filters or spreadsheet escaping.');
$crypto=['entry_date'=>$date,'direction'=>'income','account'=>'crypto','tax_kind'=>'taxable','purpose'=>'own_receipt','order_id'=>$id,'amount_czk'=>'0,01','description'=>'Krypto','currency'=>'BTC','foreign_amount'=>'0.00000001','valuation_note'=>'Ocenění dle dokladu BTC-1'];
$tax->addEntry($crypto);
$reject(fn()=>$tax->addEntry(array_replace($crypto,['valuation_note'=>''])));
foreach (['0.001','-1','1e3','NaN'] as $amount) $reject(fn()=>TaxMoney::cents($amount));
$assert(TaxMoney::cents('1 234,56')===123456,'Czech amount parsed incorrectly.');
$asset=['kind'=>'receivable','opened_on'=>$date,'amount_czk'=>'250,75','description'=>'Pohledávka '.$suffix,'reference'=>'REF-'.$suffix,'note'=>'Záloha','request_key'=>bin2hex(random_bytes(16))];
$recordId=$register->save(0,$asset,1);$record=$register->byId($recordId);
$register->save($recordId,array_replace($record,['closed_on'=>'2096-07-01','reason'=>'Zaplaceno']),1);
$reject(fn()=>$register->save($recordId,array_replace($record,['amount_czk'=>'100','reason'=>'Stará verze']),1));
$record=$register->byId($recordId);$register->save($recordId,array_replace($record,['closed_on'=>'','reason'=>'Oprava data']),1);
$assert($register->byId($recordId)['closed_on']===null && count($register->history($recordId))===3,'Register cannot reopen or lost audit.');
$inventoryId=$register->save(0,['kind'=>'inventory_stock','opened_on'=>'2096-12-31','amount_czk'=>'200,25','book_value_czk'=>'250,75','description'=>'Inventura '.$suffix,'quantity'=>'2 ks','note'=>'Pořizovací ocenění'],1);
$adjustBefore=$register->adjustments($year);
$adjustId=$register->save(0,['kind'=>'expense_add','opened_on'=>'2096-12-31','amount_czk'=>'20,25','description'=>'Odpis '.$suffix,'note'=>'Podklad k odpisu'],1);
$assert(abs((float)$register->adjustments($year)['expenses']-(float)$adjustBefore['expenses']-20.25)<0.0001,'Noncash adjustment missing.');
$assert($tax->summary($year)['expenses']===$expenses,'Inventory or adjustment created fictitious cash payment.');
$register->void($adjustId,1,1,'Chybný odpis');$assert($register->adjustments($year)===$adjustBefore,'Voided adjustment still counted.');
$db->insert('shop_invoices',['order_id'=>$id,'order_number'=>'EVID-'.$suffix,'document_number'=>'F-EVID-'.$suffix,'issue_date'=>$date,'due_date'=>$date,'seller_json'=>'{"name":"Podnikatel"}','buyer_json'=>'{"name":"Zákazník"}','items_json'=>'[]','subtotal_czk'=>122,'shipping_czk'=>0,'total_czk'=>122]);
$invoiceId=(int)$db->insertId();$beforeCredit=$tax->summary($year);
$credit=$corrections->issue($invoiceId,['amount_czk'=>'12,25','issue_date'=>$date,'reason'=>'Vrácení části služby','request_key'=>bin2hex(random_bytes(16))],1);
$assert($corrections->byId($credit)['amount_czk']==='12.25' && $tax->summary($year)===$beforeCredit,'Credit note changed cash or lost cents.');
$reject(fn()=>$corrections->issue($invoiceId,['amount_czk'=>'110','issue_date'=>$date,'reason'=>'Překročení vlastní faktury'],1));
$corrections->void($credit,'Chybná výše',1);
$corrections->issue($invoiceId,['amount_czk'=>'122','issue_date'=>$date,'reason'=>'Celá služba'],1);
$assert(count($corrections->forInvoice($invoiceId))===2,'Voided credit overwritten.');
$csv=fopen('php://temp','w+b');$funds->writeBalancesCsv($csv,$year);rewind($csv);$assert(str_contains(stream_get_contents($csv),'EVID-'.$suffix),'Annual entrusted export missing.');fclose($csv);
// Re-running the entire migration must not reclassify deliberately edited rows.
$db->query('UPDATE shop_schema_updates SET schema_hash=%s WHERE id=1',str_repeat('0',64));
(new SchemaUpdater($db,dirname(__DIR__).'/database/schema.sql'))->apply();
$assert($tax->entry((int)$entry['id'])['amount_czk']==='122.15','Repeated migration rewrote journal.');
echo "OSVC evidence database integration passed.\n";
